//! a project's `api.lock`: the lockfile `by generate-api-file` writes and a language server
//! checks, generated by one function so that the two agree on every byte
//!
//! see [`ty_python_semantic::api_lockfile`] for what the lockfile says

use ruff_db::files::{File, FilePath};
use ruff_db::system::{System, SystemPath, SystemPathBuf};
use ruff_python_ast::PythonVersionDeserializationError;
use ty_python_semantic::api_lockfile::{ApiLockTarget, generate_api_lockfile};

use crate::{Db, Project};

/// the name of the lockfile, which a project keeps in its root directory
pub const API_LOCK_FILE_NAME: &str = "api.lock";

#[salsa::tracked]
impl Project {
    /// where the project's lockfile is: `api.lock` in its root directory
    pub fn api_lock_path(self, db: &dyn Db) -> SystemPathBuf {
        self.root(db).join(API_LOCK_FILE_NAME)
    }

    /// the lockfile of the project for `target`, as the project's files read in `db`
    ///
    /// a query, since a language server asks for it again after every edit: an edit that
    /// changes nothing it says leaves it as it was, rather than generating it again
    #[salsa::tracked(returns(deref), heap_size=ruff_memory_usage::heap_size)]
    pub fn api_lock(self, db: &dyn Db, target: ApiLockTarget) -> Box<str> {
        generate_api_lockfile(db, self.program(db), api_lock_files(db, self), target)
            .into_boxed_str()
    }
}

/// the lockfile at `path` as `system` reads it, `None` where there is none. one that is there
/// but cannot be read, not being utf-8 among other reasons, is an error
pub fn read_api_lock(system: &dyn System, path: &SystemPath) -> std::io::Result<Option<String>> {
    match system.read_to_string(path) {
        Ok(text) => Ok(Some(text)),
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => Ok(None),
        Err(error) => Err(error),
    }
}

/// the target a lockfile is generated for in place of `existing`: the one its `#python:` header
/// names, or the project's where there is no lockfile or it names none
pub fn api_lock_target(
    existing: Option<&str>,
) -> Result<ApiLockTarget, PythonVersionDeserializationError> {
    existing
        .and_then(ApiLockTarget::of_lockfile)
        .unwrap_or(Ok(ApiLockTarget::Project))
}

/// the files the lockfile of `project` describes, in the order it walks them: the project's
/// first-party modules. what a build wrote is not among the project's files: see
/// [`crate::build_output`]
fn api_lock_files(db: &dyn Db, project: Project) -> Vec<File> {
    let mut files: Vec<(&SystemPath, File)> = project
        .files(db)
        .iter()
        .filter_map(|file| match file.path(db) {
            FilePath::System(path) => Some((&**path, file)),
            _ => None,
        })
        .filter(|(_, file)| {
            ty_module_resolver::file_to_module(db, db.program_file(*file).resolver_file(db))
                .and_then(|module| module.search_path(db).cloned())
                .is_some_and(|search_path| search_path.is_first_party())
        })
        .collect();
    files.sort_by_key(|(path, _)| *path);
    files.into_iter().map(|(_, file)| file).collect()
}

#[cfg(test)]
mod tests {
    use ruff_db::system::{DbWithWritableSystem as _, SystemPathBuf};
    use ruff_db::testing::find_will_execute_event_by_name;
    use ty_python_semantic::api_lockfile::ApiLockTarget;

    use crate::db::testing::TestDb;
    use crate::{Db as _, ProjectMetadata};

    /// the lockfile, and whether asking for it generated it
    fn api_lock(db: &mut TestDb) -> (String, bool) {
        let lockfile = db
            .project()
            .api_lock(db, ApiLockTarget::Project)
            .to_string();
        let events = db.take_salsa_events();
        let generated =
            find_will_execute_event_by_name(db, "Project::api_lock_", None, &events).is_some();
        (lockfile, generated)
    }

    /// asked for again, as a language server asks after every edit, the lockfile is generated
    /// again only where an edit changed what it says
    #[test]
    fn the_lockfile_is_generated_again_only_after_a_change() -> anyhow::Result<()> {
        let project = ProjectMetadata::new("test", SystemPathBuf::from("/"));
        let mut db = TestDb::with_salsa_events(project);
        db.write_file("main.py", "X: int = 1\n")?;

        let (first, generated) = api_lock(&mut db);
        assert!(generated);
        assert!(first.ends_with("\nmain.X:v=builtins.int\n"), "{first}");
        assert_eq!(api_lock(&mut db), (first, false));

        db.write_file("main.py", "X: str = \"\"\n")?;
        let (edited, generated) = api_lock(&mut db);
        assert!(generated);
        assert!(edited.ends_with("\nmain.X:v=builtins.str\n"), "{edited}");
        Ok(())
    }
}
